  cross(base, sub(p4, p2)) === 0 &&
  cross(base, sub(p5, p2)) === 0;

const sameMidpoint =
  p2[0] + p3[0] === p4[0] + p5[0] &&
  p2[1] + p3[1] === p4[1] + p5[1];

const side1 = cross(base, sub(p1, p2));
const side6 = cross(base, sub(p6, p2));

